import{z as d,x as A,o as E,c as B,q as r,j as t,D as l,d as n,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"循环展开与剥离","description":"","frontmatter":{"title":"循环展开与剥离","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/loop-unroll-peel.md","filePath":"cs/loop-unroll-peel.md","lastUpdated":1791063341000}'),p={name:"cs/loop-unroll-peel.md"};function m(u,a,D,h,k,f){const o=A("Mermaid");return E(),B("div",null,[a[2]||(a[2]=r('<h1 id="循环展开与剥离" tabindex="-1">循环展开与剥离 <a class="header-anchor" href="#循环展开与剥离" aria-label="Permalink to &quot;循环展开与剥离&quot;">​</a></h1><div class="epigraph"><p>展开把循环体复制 $k$ 次，减少分支与暴露调度窗口；剥离处理不对齐的头几圈，使主循环满足向量或缓存假设。</p><footer>—— 据 Allen and Cocke 变换目录；龙书循环展开；Kennedy and Allen, Optimizing Compilers for Modern Architectures 整理</footer></div><p>上一课<a href="/cs/strength-reduction-iv">强度削弱</a>减每圈算术。缺口是<strong>圈结构本身</strong>：展开（unroll）、剥离（peel）、余数循环。本课钉何时复制体，不写自动向量化的依赖分析——后课。也不把展开当软件流水。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每圈一次条件跳，对小体是开销；超标量要更多独立指令。展开 \\(k\\)：计数器步进 \\(k\\)，体复制，IV 已削弱则可直接写 \\(k\\) 份地址。余数：<code>n%k</code> 用剥离或收尾循环。缺口是<strong>因子 \\(k\\) 与代码大小</strong>，不是 IV 识别。</p><p>完全展开：行程编译期常量则变成直线代码，再 SCCP/DCE。</p><p><span class="marginnote">数字实例：\\(n=10\\)、\\(k=4\\) 时，主循环体复制 4 份、只跑 2 圈就处理完 8 个元素，剩下 \\(10 \\bmod 4 = 2\\) 个交给收尾循环或剥离段。结果与原始循环跑 10 圈完全等价，但条件跳转从 10 次降到约 3 次。</span></p><h3 id="剥离不是展开" tabindex="-1">剥离不是展开 <a class="header-anchor" href="#剥离不是展开" aria-label="Permalink to &quot;剥离不是展开&quot;">​</a></h3><p>剥离：先跑 1 至若干圈（处理对齐、第一次迭代的特殊别名），再进主循环。展开是主循环体内复制。常组合：剥到对齐，再按向量宽度展开。</p><p><span class="marginnote">Kennedy–Allen 的教材。龙书。PGO 后课用轮廓选 \\(k\\)。本课静态启发：体大小、行程估计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计：体指令数 × \\(k\\) 是否超过阈值。已知 <code>n</code> 则选整除的 \\(k\\)。未知则收尾循环。剥：对「首圈必执行的不变量 store」有时比 LICM 更易证明。</p>',12)),(E(),t(i,null,{default:l(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20PEEL%5B%22%E5%89%A5%E7%A6%BB%E5%AF%B9%E9%BD%90%22%5D%0A%20%20PEEL%20--%3E%20UN%5B%22%E5%B1%95%E5%BC%80%20k%22%5D%0A%20%20UN%20--%3E%20EPIL%5B%22%E6%94%B6%E5%B0%BE%E4%BD%99%E6%95%B0%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与寄存器压力：展开拉长存活区间，着色更难——后课线性扫描会痛。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：展开像把一份菜谱复印 4 份贴成一张大抄——炒菜时少翻 3 次页（省分支跳转），但纸变大（代码体积膨胀），灶台上要同时摆的料也变多（活跃值挤占寄存器）。翻页省下的时间若被摆料抵消，就白展开了。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"不要展开带可变行程且巨大的体。调试：行号映射多份体到同一源行，DWARF 后课。不要改变浮点归约顺序除非 fast-math。",-1)),a[7]||(a[7]=e("p",null,"并行：展开不创造并行；只给调度与向量化窗口。",-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易以为展开后几份循环体是「同时跑」的。实际上它们仍严格按原顺序执行，展开只是给了 CPU 更大的窗口去挑互不相关的指令填满空闲的流水槽；真正的并行要靠向量化或软件流水。")],-1)),(E(),t(i,null,{default:l(()=>[s(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20LR%0A%20%20K%5B%22%E5%B1%95%E5%BC%80%E5%9B%A0%E5%AD%90%20k%20%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%20B%5B%22%E5%88%86%E6%94%AF%E5%BC%80%E9%94%80%E4%B8%8B%E9%99%8D%22%5D%0A%20%20K%20--%3E%20SZ%5B%22%E4%BB%A3%E7%A0%81%E4%BD%93%E7%A7%AF%E4%B8%8A%E5%8D%87%22%5D%0A%20%20K%20--%3E%20RP%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E5%8E%8B%E5%8A%9B%E4%B8%8A%E5%8D%87%22%5D%0A%20%20RP%20--%3E%20LR2%5B%22%E5%AD%98%E6%B4%BB%E5%8C%BA%E9%97%B4%E5%8F%98%E9%95%BF%22%5D%0A%20%20LR2%20--%3E%20COL%5B%22%E7%9D%80%E8%89%B2%E5%8F%AF%E8%83%BD%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20COL%20--%3E%20SPILL%5B%22%E6%8F%92%E5%85%A5%E6%BA%A2%E5%87%BA%E8%AE%BF%E5%AD%98%22%5D%0A%20%20SPILL%20--%3E%20NET%5B%22%E5%87%80%E6%94%B6%E7%9B%8A%20%3D%20%E5%88%86%E6%94%AF%E8%8A%82%E7%9C%81%20%E2%88%92%20%E6%BA%A2%E5%87%BA%E4%B8%8E%E8%86%A8%E8%83%80%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20B%20--%3E%20NET%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多面体。后课默认：小体、常行程可展开；对齐用剥离。下一课交换与分块：改迭代嵌套的顺序与粒度。</p><p>也不把展开当混淆（故意胀代码）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>展开复制体、降分支、开调度窗口；余数要收尾。</li><li>剥离服务对齐与首圈特例。</li><li>\\(k\\) 受代码大小与寄存器压力约束。</li><li>出处：Allen and Cocke；Kennedy and Allen；龙书。</li></ul>',5))])}const C=d(p,[["render",m]]);export{P as __pageData,C as default};
